import React from 'react';
import { BrowserRouter, Routes, Route, useLocation } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { CartProvider } from './context/CartContext';

import Navbar from './components/common/Navbar';
import Footer from './components/common/Footer';
import ProtectedRoute from './components/common/ProtectedRoute';

import Home from './pages/marketplace/Home';
import Products from './pages/marketplace/Products';
import ProductDetail from './pages/marketplace/ProductDetail';

// Lazy loaded pages
const Cart = React.lazy(() => import('./pages/marketplace/Cart'));
const Checkout = React.lazy(() => import('./pages/marketplace/Checkout'));
const OrderSuccess = React.lazy(() => import('./pages/marketplace/OrderSuccess'));
const MyOrders = React.lazy(() => import('./pages/marketplace/MyOrders'));
const OrderTracking = React.lazy(() => import('./pages/marketplace/OrderTracking'));
const Profile = React.lazy(() => import('./pages/marketplace/Profile'));
const Wishlist = React.lazy(() => import('./pages/marketplace/Wishlist'));

// Auth pages
const CustomerLogin = React.lazy(() => import('./pages/auth/CustomerLogin'));
const CustomerRegister = React.lazy(() => import('./pages/auth/CustomerRegister'));
const VendorLogin = React.lazy(() => import('./pages/auth/VendorLogin'));
const VendorRegister = React.lazy(() => import('./pages/auth/VendorRegister'));
const AdminLogin = React.lazy(() => import('./pages/auth/AdminLogin'));
const WarehouseLogin = React.lazy(() => import('./pages/auth/WarehouseLogin'));

// Dashboard pages
const AdminDashboard = React.lazy(() => import('./pages/admin/AdminDashboard'));
const ManageVendors = React.lazy(() => import('./pages/admin/ManageVendors'));
const VendorKYCReview = React.lazy(() => import('./pages/admin/VendorKYCReview'));
const ManageProducts = React.lazy(() => import('./pages/admin/ManageProducts'));
const ManageOrders = React.lazy(() => import('./pages/admin/ManageOrders'));
const ManageUsers = React.lazy(() => import('./pages/admin/ManageUsers'));
const AdminAnalytics = React.lazy(() => import('./pages/admin/AdminAnalytics'));
const ManageWarehouse = React.lazy(() => import('./pages/admin/ManageWarehouse'));
const AddWarehouseStaff = React.lazy(() => import('./pages/admin/AddWarehouseStaff'));
const VendorDashboard = React.lazy(() => import('./pages/vendor/VendorDashboard'));
const WarehouseDashboard = React.lazy(() => import('./pages/warehouse/WarehouseDashboard'));
const ShipmentList = React.lazy(() => import('./pages/warehouse/ShipmentList'));
const ShipmentDetail = React.lazy(() => import('./pages/warehouse/ShipmentDetail'));

function AppLayout() {
  const location = useLocation();
  const isDashboard = location.pathname.startsWith('/admin') || location.pathname.startsWith('/warehouse') || location.pathname.startsWith('/vendor');

  return (
    <>
      {!isDashboard && <Navbar />}
      <main style={{ minHeight: '70vh' }}>
        <React.Suspense fallback={<div style={{padding:40}}>Loading...</div>}>
          <Routes>
            {/* Public Routes */}
            <Route path="/" element={<Home />} />
            <Route path="/products" element={<Products />} />
            <Route path="/products/:id" element={<ProductDetail />} />
            <Route path="/cart" element={<Cart />} />
            <Route path="/checkout" element={<Checkout />} />
            <Route path="/order-success" element={<OrderSuccess />} />
            <Route path="/my-orders" element={<MyOrders />} />
            <Route path="/track/:id" element={<OrderTracking />} />
            <Route path="/wishlist" element={<Wishlist />} />

            {/* Auth Routes */}
            <Route path="/login" element={<CustomerLogin />} />
            <Route path="/register" element={<CustomerRegister />} />
            <Route path="/vendor/login" element={<VendorLogin />} />
            <Route path="/vendor/register" element={<VendorRegister />} />
            <Route path="/admin/login" element={<AdminLogin />} />
            <Route path="/warehouse/login" element={<WarehouseLogin />} />

            {/* Customer Protected Routes */}
            <Route path="/account" element={
              <ProtectedRoute>
                <Profile />
              </ProtectedRoute>
            } />

            {/* Vendor Protected Routes */}
            <Route path="/vendor" element={
              <ProtectedRoute allowedRoles={['vendor']}>
                <VendorDashboard />
              </ProtectedRoute>
            } />

            {/* Admin Protected Routes */}
            <Route path="/admin" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <AdminDashboard />
              </ProtectedRoute>
            } />
            <Route path="/admin/vendors" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <ManageVendors />
              </ProtectedRoute>
            } />
            <Route path="/admin/vendors/kyc" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <VendorKYCReview />
              </ProtectedRoute>
            } />
            <Route path="/admin/products" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <ManageProducts />
              </ProtectedRoute>
            } />
            <Route path="/admin/orders" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <ManageOrders />
              </ProtectedRoute>
            } />
            <Route path="/admin/users" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <ManageUsers />
              </ProtectedRoute>
            } />
            <Route path="/admin/analytics" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <AdminAnalytics />
              </ProtectedRoute>
            } />
            <Route path="/admin/warehouse" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <ManageWarehouse />
              </ProtectedRoute>
            } />
            <Route path="/admin/warehouse/staff" element={
              <ProtectedRoute allowedRoles={['admin']}>
                <AddWarehouseStaff />
              </ProtectedRoute>
            } />

            {/* Warehouse Protected Routes */}
            <Route path="/warehouse" element={
              <ProtectedRoute allowedRoles={['warehouse']}>
                <WarehouseDashboard />
              </ProtectedRoute>
            } />
            <Route path="/warehouse/shipments" element={
              <ProtectedRoute allowedRoles={['warehouse']}>
                <ShipmentList />
              </ProtectedRoute>
            } />
            <Route path="/warehouse/shipments/:id" element={
              <ProtectedRoute allowedRoles={['warehouse']}>
                <ShipmentDetail />
              </ProtectedRoute>
            } />

            <Route path="*" element={<div style={{padding:40}}>Page not found</div>} />
          </Routes>
        </React.Suspense>
      </main>
      {!isDashboard && <Footer />}
    </>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <CartProvider>
        <BrowserRouter>
          <AppLayout />
        </BrowserRouter>
      </CartProvider>
    </AuthProvider>
  );
}
